  values (b, 'scr', 'NEG-AUTO', array['NEG-AUTO-01','NEG-AUTO-36','NEG-AUTO-05']::text[], 'Taller La Nueva Era', 'active', 'self', (select id from users where phone = '+15705559553'), 'local', '504 Mulberry St, Scranton PA', st_geogfromtext('POINT(-75.652804 41.413403)'), false, null, '+15705550166', true, array['es']::text[], '{"es":"Taller mecánico de todo tipo de reparaciones en Scranton desde 2018. Mecánicos con experiencia y garantía por escrito. Apartas piezas desde la app y las recoges en 48 horas. Hablamos español e inglés.","en":"Full-service repair shop in Scranton since 2018. Experienced mechanics and a written warranty. Reserve parts in the app and pick them up within 48 hours. We speak Spanish and English."}'::jsonb, 2018, array['acepta-tarjeta','presupuesto-gratis','con-seguro','plan-de-pagos','sala-de-espera','estacionamiento','productos-a-la-venta','apartado']::text[], array['walkin','cita','online','diagfree','garantia','tienda','seguro','sameday']::text[], '{local}', '{"m":"bay","mk":["chrysler","nissan","dodge","chevy","honda","gmc","toyota","mazda","mercedes","acura","ford","hyundai","kia"],"veh":["c","s","t"],"auto":1,"bays":6,"warr":[36,36000],"tarjeta":{"eta":{"es":"Sin cita hasta las 4 PM","en":"Booking today or tomorrow"},"fee":{"es":"Diagnóstico gratis","en":"Free diagnosis"},"offer":{"es":"Revisión de 20 puntos gratis con cada cambio de aceite","en":"Free 20-point check with every oil change"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%230B3D5C''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23FFFFFF''%20text-anchor%3D''middle''%3ETN%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','citas','cot','staff','nov','shop']::text[], 'emp', true);
