  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Dan el estimado antes de reparar?","en":"Do you give an estimate before repairing?"}'::jsonb, '{"es":"Sí. Te mandamos el estimado por la app, con fotos y cada línea por separado, y tú decides qué se hace. No tocamos nada sin tu OK.","en":"Yes. We send the estimate in the app, with photos and each line separate, and you decide what is done. We touch nothing without your OK."}'::jsonb, 0);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Tienen garantía?","en":"Do you offer a warranty?"}'::jsonb, '{"es":"Sí: 36 meses o 36,000 millas en piezas y mano de obra, por escrito.","en":"Yes: 36 months or 36,000 miles on parts and labor, in writing."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo esperar o debo dejarlo?","en":"Can I wait or do I need to leave it?"}'::jsonb, '{"es":"Depende del trabajo: cada servicio dice si es mientras esperas, si lo dejas o si funciona de las dos maneras. Si lo dejas, te avisamos por mensaje cuando esté listo.","en":"It depends on the job: each service says whether you wait, leave it, or either way. If you leave it, we message you when it is ready."}'::jsonb, 2);
