  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo esperar o debo dejarlo?","en":"Can I wait or do I need to leave it?"}'::jsonb, '{"es":"Depende del trabajo: cada servicio dice si es mientras esperas, si lo dejas o si funciona de las dos maneras. Si lo dejas, te avisamos por mensaje cuando esté listo.","en":"It depends on the job: each service says whether you wait, leave it, or either way. If you leave it, we message you when it is ready."}'::jsonb, 2);
