  values (b, 'alw', 'NEG-AUTO', array['NEG-AUTO-04','NEG-AUTO-09','NEG-AUTO-10']::text[], 'Scanner Pro Allentown', 'active', 'self', (select id from users where phone = '+15705559581'), 'local', '26 N 10th St, Allentown PA', st_geogfromtext('POINT(-75.479992 40.604344)'), false, null, '+16105550183', true, array['es','en']::text[], '{"es":"Diagnóstico con escáner y electrónica del carro en Allentown desde 2010. Mecánicos con experiencia y garantía por escrito. Apartas piezas desde la app y las recoges en 48 horas. Hablamos español e inglés.","en":"Scanner diagnostics and car electronics in Allentown since 2010. Experienced mechanics and a written warranty. Reserve parts in the app and pick them up within 48 hours. We speak Spanish and English."}'::jsonb, 2010, array['acepta-tarjeta','presupuesto-gratis','con-seguro','plan-de-pagos','sala-de-espera','estacionamiento','garantia','productos-a-la-venta','apartado']::text[], array['walkin','cita','online','diagfree','garantia','tienda','inspector','seguro','sameday','y10']::text[], '{local}', '{"m":"bay","mk":["bmw","ford","mazda","gmc","ram","lexus","subaru","hyundai","jeep","toyota","mercedes"],"veh":["c","s"],"auto":1,"bays":6,"warr":[12,12000],"tarjeta":{"eta":{"es":"Resultados el mismo día","en":"Same-day results"},"fee":{"es":"Diagnóstico $84 · se descuenta","en":"Diagnosis $84 · credited to the job"},"offer":{"es":"Luz de check engine: lectura gratis","en":"Check engine light: free reading"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%2322313F''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23F4B942''%20text-anchor%3D''middle''%3ESP%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','citas','cot','staff','nov','shop']::text[], 'emp', true);
