  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo esperar o debo dejarlo?","en":"Can I wait or do I need to leave it?"}'::jsonb, '{"es":"Depende del trabajo: cada servicio dice si es mientras esperas, si lo dejas o si funciona de las dos maneras. Si lo dejas, te avisamos por mensaje cuando esté listo.","en":"It depends on the job: each service says whether you wait, leave it, or either way. If you leave it, we message you when it is ready."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Hacen la inspección de PA?","en":"Do you do the PA inspection?"}'::jsonb, '{"es":"Preguntamos por la estación más cercana y te ayudamos a prepararlo para pasar.","en":"We point you to the nearest station and help you get it ready to pass."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Hablan español?","en":"Do you speak Spanish?"}'::jsonb, '{"es":"Sí, todo el equipo. También en inglés, si lo prefieres.","en":"Yes, the whole team. English too, if you prefer."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo se paga?","en":"How do I pay?"}'::jsonb, '{"es":"Con tarjeta en la app, o en efectivo o tarjeta en el taller. El total va por escrito antes de empezar.","en":"By card in the app, or cash or card at the shop. The total is in writing before we start."}'::jsonb, 5);
