insert into operation_lines (operation_id, item_id, name, qty, unit_price_cents, line_total_cents, tax_pct)
select o.id, i.id, coalesce(i.name, jsonb_build_object('es', o.details#>>'{svc,es}', 'en', o.details#>>'{svc,en}')), 1, o.subtotal_cents, o.subtotal_cents, 0
  from operations o left join items i on i.business_id = o.business_id and i.module = 'svc' and i.removed_at is null and i.name->>'es' = o.details#>>'{svc,es}'
 where o.details->>'demo' = 'c' and o.details->>'cat' = 'NEG-AUTO' and o.kind = 'appointment' and not exists (select 1 from operation_lines l where l.operation_id = o.id);
insert into payments (operation_id, user_id, business_id, city_id, kind, method, stripe_payment_intent, amount_cents, fee_cents, status, card_brand, card_last4, held_at, captured_at, simulated, created_at)
select o.id, o.user_id, o.business_id, o.city_id, 'full', 'card', 'pi_sim_democ_' || o.number, o.total_cents, round(o.total_cents * 0.08)::int, 'captured', (array['visa', 'mastercard', 'visa', 'amex'])[1 + (o.id % 4)::int], lpad(((o.id * 7919) % 10000)::text, 4, '0'), o.confirmed_at, o.done_at, true, o.sent_at
  from operations o where o.details->>'demo' = 'c' and o.details->>'cat' = 'NEG-AUTO' and o.kind = 'appointment' and o.pay_status = 'captured' and o.total_cents > 0 and not exists (select 1 from payments p where p.operation_id = o.id) on conflict do nothing;
