  from (values ('A-3200205', 'Pastillas de cerámica (eje)', 1, 5700), ('A-3200205', 'Discos de freno (par)', 1, 9100), ('A-3200206', 'Líquido de frenos DOT 3', 1, 900), ('A-3200207', 'Líquido de frenos DOT 3', 2, 900), ('A-3200208', 'Pastillas de cerámica (eje)', 2, 5700), ('A-3200209', 'Líquido de frenos DOT 3', 2, 900), ('A-3200210', 'Pastillas de cerámica (eje)', 2, 5700), ('A-3200211', 'Discos de freno (par)', 1, 9100), ('A-3200212', 'Discos de freno (par)', 2, 9100), ('A-3200212', 'Pastillas de cerámica (eje)', 1, 5700), ('A-3200213', 'Líquido de frenos DOT 3', 1, 900), ('A-3200213', 'Discos de freno (par)', 2, 9100), ('A-3200214', 'Pastillas de cerámica (eje)', 2, 5700), ('A-3200214', 'Líquido de frenos DOT 3', 2, 900), ('A-3200215', 'Líquido de frenos DOT 3', 2, 900), ('A-3200215', 'Discos de freno (par)', 2, 9100), ('A-3200216', 'Discos de freno (par)', 2, 9100), ('A-3200217', 'Discos de freno (par)', 1, 9100), ('A-3200217', 'Pastillas de cerámica (eje)', 2, 5700), ('A-3200218', 'Líquido de frenos DOT 3', 1, 900)) as v(num, es, qty, price)
  join operations o on o.number = v.num left join items i on i.business_id = o.business_id and i.module = 'shop' and i.name->>'es' = v.es
